def main() -> None:
    all_topics = sorted({t for ts in TECH_TOPICS.values() for t in ts})
    lines = [
        '"""Extended topic snippets — generated/curated for all TECH_TOPICS keys."""',
        "from __future__ import annotations",
        "",
        "EXTENDED_TOPIC_SNIPPETS: dict[str, dict[str, str]] = {",
    ]
    for topic in all_topics:
        if topic not in SPECS:
            label = topic.replace("-", " ").title()
            spec = (
                label,
                f"core concepts and daily workflows for {label.lower()}",
                f"status commands, logs, and configuration related to {label.lower()}",
                f"{label} misconfiguration causes user-visible failures or operational risk",
                f"{label} meets expected health checks after your changes",
            )
        else:
            spec = SPECS[topic]
        label, concept, inspect, symptom, verify = spec
        lines.append(f"    {topic!r}: {{")
        lines.append(f"        'label': {label!r},")
        lines.append(f"        'concept': {concept!r},")
        lines.append(f"        'inspect': {inspect!r},")
        lines.append(f"        'symptom': {symptom!r},")
        lines.append(f"        'verify': {verify!r},")
        lines.append("    },")
    lines.append("}")
    out = Path(__file__).parent / "topic_snippets_extended.py"
    out.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"Wrote {out} with {len(all_topics)} topics ({len(SPECS)} detailed, {len(all_topics)-len(SPECS)} fallback)")


if __name__ == "__main__":
    main()
